PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'onboarding' CHECK(status IN ('onboarding','active','paused','banned','deleted')), age_assured_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE TABLE auth_identities (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL CHECK(provider IN ('email','phone','apple')), provider_subject TEXT NOT NULL, verified_at INTEGER NOT NULL, UNIQUE(provider,provider_subject));
CREATE TABLE email_verifications (id TEXT PRIMARY KEY, subject TEXT NOT NULL, code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL, consumed_at INTEGER, link_user_id TEXT REFERENCES users(id));
CREATE TABLE phone_verifications (id TEXT PRIMARY KEY, subject TEXT NOT NULL, code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL, consumed_at INTEGER, link_user_id TEXT REFERENCES users(id));
CREATE TABLE refresh_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), family_id TEXT NOT NULL, refresh_hash TEXT NOT NULL UNIQUE, access_hash TEXT NOT NULL UNIQUE, access_expires INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER, revoked_at INTEGER, created_at INTEGER NOT NULL);
CREATE INDEX session_family ON refresh_sessions(family_id);
CREATE TABLE profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), display_name TEXT NOT NULL DEFAULT '', date_of_birth TEXT, bio TEXT NOT NULL DEFAULT '', gender TEXT NOT NULL DEFAULT '', relationship_intent TEXT NOT NULL DEFAULT 'serious', interests TEXT NOT NULL DEFAULT '[]', languages TEXT NOT NULL DEFAULT '["English"]', lifestyle TEXT NOT NULL DEFAULT '{}', date_readiness TEXT NOT NULL DEFAULT 'chat_first', onboarding_status TEXT NOT NULL DEFAULT 'incomplete', visibility_status TEXT NOT NULL DEFAULT 'visible' CHECK(visibility_status IN ('visible','hidden')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE dating_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id), min_age INTEGER NOT NULL DEFAULT 18 CHECK(min_age>=18), max_age INTEGER NOT NULL DEFAULT 99 CHECK(max_age>=min_age), genders TEXT NOT NULL DEFAULT '[]', radius_km INTEGER NOT NULL DEFAULT 50 CHECK(radius_km BETWEEN 1 AND 500), intentions TEXT NOT NULL DEFAULT '[]', passport_city TEXT);
CREATE TABLE user_locations (user_id TEXT PRIMARY KEY REFERENCES users(id), latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180), city TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE privacy_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id), show_distance INTEGER NOT NULL DEFAULT 0 CHECK(show_distance IN (0,1)), show_activity INTEGER NOT NULL DEFAULT 0 CHECK(show_activity IN (0,1)), read_receipts INTEGER NOT NULL DEFAULT 0 CHECK(read_receipts IN (0,1)), incognito INTEGER NOT NULL DEFAULT 0 CHECK(incognito IN (0,1)));
CREATE TABLE profile_photos (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), object_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), position INTEGER NOT NULL DEFAULT 0, content_hash TEXT, upload_hash TEXT, upload_expires INTEGER, created_at INTEGER NOT NULL, UNIQUE(user_id,content_hash));
CREATE INDEX photos_user ON profile_photos(user_id,status,position);
CREATE TABLE swipes (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL CHECK(action IN ('like','pass','super_like')), created_at INTEGER NOT NULL, CHECK(actor_id<>target_id), UNIQUE(actor_id,target_id));
CREATE INDEX swipes_incoming ON swipes(target_id,action,created_at);
CREATE TABLE matches (id TEXT PRIMARY KEY, user_a TEXT NOT NULL REFERENCES users(id), user_b TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','unmatched','blocked')), created_at INTEGER NOT NULL, CHECK(user_a<user_b), UNIQUE(user_a,user_b));
CREATE INDEX matches_b ON matches(user_b,status);
CREATE TABLE conversations (id TEXT PRIMARY KEY, match_id TEXT NOT NULL UNIQUE REFERENCES matches(id), created_at INTEGER NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), sender_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL, body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), reply_to TEXT REFERENCES messages(id), created_at INTEGER NOT NULL, sequence INTEGER NOT NULL, UNIQUE(conversation_id,sender_id,client_id), UNIQUE(conversation_id,sequence));
CREATE INDEX messages_history ON messages(conversation_id,sequence);
CREATE TABLE blocks (actor_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, CHECK(actor_id<>target_id), PRIMARY KEY(actor_id,target_id));
CREATE TABLE reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, details TEXT NOT NULL, conversation_id TEXT REFERENCES conversations(id), created_at INTEGER NOT NULL);
CREATE TABLE moderation_cases (id TEXT PRIMARY KEY, report_id TEXT NOT NULL UNIQUE REFERENCES reports(id), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved')), priority TEXT NOT NULL DEFAULT 'normal', resolution TEXT, assigned_to TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX case_queue ON moderation_cases(status,priority,created_at);
CREATE TABLE admin_audit_logs (id TEXT PRIMARY KEY, actor TEXT NOT NULL, role TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE security_events (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE subscription_products (id TEXT PRIMARY KEY, tier TEXT NOT NULL CHECK(tier IN ('plus','gold','elite')), kind TEXT NOT NULL CHECK(kind IN ('subscription','consumable')), allowance INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE subscription_entitlements (user_id TEXT PRIMARY KEY REFERENCES users(id), tier TEXT NOT NULL CHECK(tier IN ('free','plus','gold','elite')), expires_at INTEGER NOT NULL, original_transaction_id TEXT UNIQUE, updated_at INTEGER NOT NULL);
CREATE TABLE purchase_transactions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES subscription_products(id), original_id TEXT NOT NULL, expires_at INTEGER, revoked_at INTEGER, environment TEXT NOT NULL, verified_at INTEGER NOT NULL);
CREATE TABLE consumable_balances (user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('super_like','boost')), balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0), PRIMARY KEY(user_id,kind));
CREATE TABLE consumable_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, amount INTEGER NOT NULL, reference TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE outbox_events (id TEXT PRIMARY KEY, kind TEXT NOT NULL, aggregate_id TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL, delivered_at INTEGER, UNIQUE(kind,aggregate_id));
CREATE TABLE idempotency_keys (user_id TEXT NOT NULL REFERENCES users(id), key TEXT NOT NULL, route TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(user_id,key,route));
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE data_deletion_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id), status TEXT NOT NULL, created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE data_export_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE feature_flags (name TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), updated_at INTEGER NOT NULL);
CREATE TABLE notification_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id), matches INTEGER NOT NULL DEFAULT 1, messages INTEGER NOT NULL DEFAULT 1, safety INTEGER NOT NULL DEFAULT 1, previews INTEGER NOT NULL DEFAULT 0, quiet_start INTEGER, quiet_end INTEGER);
CREATE TABLE device_registrations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token TEXT NOT NULL UNIQUE, environment TEXT NOT NULL CHECK(environment IN ('sandbox','production')), created_at INTEGER NOT NULL);
CREATE TABLE interests (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE user_interests (user_id TEXT NOT NULL REFERENCES users(id), interest_id TEXT NOT NULL REFERENCES interests(id), PRIMARY KEY(user_id,interest_id));
CREATE TABLE profile_prompts (id TEXT PRIMARY KEY, text TEXT NOT NULL);
CREATE TABLE profile_prompt_answers (user_id TEXT NOT NULL REFERENCES users(id), prompt_id TEXT NOT NULL REFERENCES profile_prompts(id), answer TEXT NOT NULL, PRIMARY KEY(user_id,prompt_id));
CREATE TABLE verification_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), provider_reference TEXT UNIQUE, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE recommendation_impressions (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), version TEXT NOT NULL, factors TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE unmatches (id TEXT PRIMARY KEY, match_id TEXT NOT NULL REFERENCES matches(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE TABLE profile_boosts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), starts_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE message_reactions (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES users(id), emoji TEXT NOT NULL, PRIMARY KEY(message_id,user_id));
CREATE TABLE conversation_settings (conversation_id TEXT NOT NULL REFERENCES conversations(id), user_id TEXT NOT NULL REFERENCES users(id), muted INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE message_receipts (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES users(id), delivered_at INTEGER, read_at INTEGER, PRIMARY KEY(message_id,user_id));
CREATE TABLE entitlement_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE moderation_actions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES moderation_cases(id), actor TEXT NOT NULL, action TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE appeals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), case_id TEXT REFERENCES moderation_cases(id), details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL);
CREATE TABLE notification_deliveries (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), event_id TEXT NOT NULL REFERENCES outbox_events(id), status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(user_id,event_id));
CREATE INDEX identity_user ON auth_identities(user_id);
CREATE INDEX session_user ON refresh_sessions(user_id,revoked_at);
CREATE INDEX discovery_profiles ON profiles(visibility_status,onboarding_status);
CREATE INDEX outbox_pending ON outbox_events(delivered_at,created_at);
CREATE INDEX reports_target ON reports(target_id,created_at);
CREATE INDEX entitlement_expiry ON subscription_entitlements(expires_at);
